<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { Trash2, ArrowRight, RefreshCw } from 'lucide-vue-next'; import { useCart } from '../../stores/cart'; import { money } from '../../utils/format'; import { errorMessage } from '../../api/http'; import EmptyState from '../../components/EmptyState.vue'; import LoadingState from '../../components/LoadingState.vue'; import ConfirmDialog from '../../components/ConfirmDialog.vue'; import BookCover from '../../components/BookCover.vue'
const cart = useCart(), loading = ref(true), error = ref(''), clear = ref(false); async function load() { loading.value = true; error.value = ''; try { await cart.refresh() } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } } onMounted(load)
</script>
<template><div class="container page"><div class="section-heading"><div><span class="eyebrow">NHỮNG LỰA CHỌN CỦA BẠN</span><h1>Giỏ sách <span class="muted">({{ cart.count }})</span></h1></div><button v-if="cart.lines.length" class="text-link" @click="clear = true"><Trash2 :size="16" /> Xóa giỏ</button></div><LoadingState v-if="loading" /><p v-if="error" class="alert error" role="alert">{{ error }} <button @click="load">Thử lại</button></p><EmptyState v-if="!cart.lines.length && !loading" title="Giỏ sách còn đang trống" text="Một người bạn mới đang chờ bạn trên kệ sách."><RouterLink to="/products" class="btn">Khám phá sách <ArrowRight :size="17" /></RouterLink></EmptyState><template v-if="cart.lines.length && !loading"><p v-for="notice in cart.notices" :key="notice" class="alert">{{ notice }}</p><div class="checkout-grid"><section class="cart-lines"><article v-for="line in cart.lines" :key="line.productId" class="cart-line"><BookCover class="cart-cover" :book="cart.products[line.productId] || { name: 'Sách không khả dụng', author: '' }" /><div><RouterLink :to="`/products/${line.productId}`"><h3>{{ cart.products[line.productId]?.name || 'Sản phẩm không khả dụng' }}</h3></RouterLink><p>{{ cart.products[line.productId]?.author }}</p><strong>{{ money(cart.products[line.productId]?.price || 0) }}</strong><p v-if="!cart.products[line.productId]?.isActive || (cart.products[line.productId]?.stockQuantity || 0) < line.quantity" class="error">Ngừng bán hoặc không đủ tồn. Vui lòng sửa giỏ.</p><label class="quantity-label">Số lượng <input type="number" min="1" max="1000" :value="line.quantity" :aria-label="`Số lượng ${cart.products[line.productId]?.name}`" @change="cart.setQuantity(line.productId, Number(($event.target as HTMLInputElement).value))"></label></div><button class="icon-btn" aria-label="Xóa sách khỏi giỏ" @click="cart.remove(line.productId)"><Trash2 :size="19" /></button></article><button class="text-link" @click="load"><RefreshCw :size="16" /> Cập nhật giá và tồn kho</button></section><aside class="summary-card"><h2>Tóm tắt đơn hàng</h2><div><span>Tạm tính</span><strong>{{ money(cart.total) }}</strong></div><div><span>Phí giao hàng</span><span class="success">Miễn phí · 0đ</span></div><div class="summary-total"><span>Tổng cộng</span><strong>{{ money(cart.total) }}</strong></div><RouterLink v-if="cart.valid && !error" to="/checkout" class="btn full">Tiến hành đặt hàng <ArrowRight :size="17" /></RouterLink><p v-else class="alert error">Cần cập nhật hoặc sửa giỏ trước khi đặt hàng.</p><small>Giá cuối cùng được xác nhận từ hệ thống khi đặt hàng. Chỉ thanh toán giả lập.</small></aside></div></template><ConfirmDialog :open="clear" title="Xóa toàn bộ giỏ sách?" message="Bạn có thể thêm sách lại bất kỳ lúc nào." @close="clear = false" @confirm="cart.lines = []; clear = false" /></div></template>